package xiaozhi.modules.aiskill;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.beans.factory.support.DefaultListableBeanFactory;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.mock.env.MockEnvironment;
import org.springframework.test.util.ReflectionTestUtils;
import com.fasterxml.jackson.databind.*;
import liquibase.*;
import liquibase.database.jvm.JdbcConnection;
import liquibase.resource.ClassLoaderResourceAccessor;
import xiaozhi.modules.ai.*;
import xiaozhi.modules.ai.AiModels.*;
import xiaozhi.modules.aicontext.*;
import xiaozhi.modules.agenttool.*;
import xiaozhi.modules.agenttool.AgentToolModels.*;
import xiaozhi.modules.conversation.*;
import xiaozhi.modules.conversation.ConversationModels.*;

/** Real new MySQL schema and normal enqueue/task/tool callback paths; no business fixture is pretended to be real data. */
@EnabledIfEnvironmentVariable(named="AI_SKILL_TEST_JDBC_URL",matches=".+")
class AiSkillPersistenceTest {
    static JdbcTemplate db;static DataSourceTransactionManager manager;static ObjectMapper json;static AtomicLong users=new AtomicLong(1500);
    long owner;String conversation;AiSkillService skills;MockEnvironment env;ConversationService conversations;AiExecutionService ai;AgentToolService tools;ConversationEvidenceService evidence;
    static <T>ObjectProvider<T> provider(Class<T> type,T value){var factory=new DefaultListableBeanFactory();factory.registerSingleton("fixture",value);return factory.getBeanProvider(type);}
    @BeforeAll static void database()throws Exception{String url=System.getenv("AI_SKILL_TEST_JDBC_URL");if(!url.matches("jdbc:mysql://127\\.0\\.0\\.1:[0-9]+/xiaozhi_ai_skill_test_[a-z0-9_]+(\\?.*)?"))throw new IllegalArgumentException("A NEW isolated ai skill schema is required");var source=new DriverManagerDataSource(url,"root",System.getenv("AI_SKILL_TEST_DB_PASSWORD"));db=new JdbcTemplate(source);manager=new DataSourceTransactionManager(source);json=new xiaozhi.modules.security.config.WebMvcConfig().jackson2HttpMessageConverter().getObjectMapper();assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE()",Long.class),"Never clean a preexisting schema");db.execute("CREATE TABLE sys_user(id BIGINT PRIMARY KEY,status TINYINT NOT NULL,super_admin TINYINT NOT NULL DEFAULT 0,username VARCHAR(80))");db.execute("CREATE TABLE ai_agent(id VARCHAR(32) PRIMARY KEY,user_id BIGINT)");for(String name:List.of("conversation","support","attachments","ai-execution","ai-provider-request-usage","agent-tools","ai-context","ai-skills"))try(var connection=source.getConnection();var migration=new Liquibase("db/changelog/"+name+".changelog.yaml",new ClassLoaderResourceAccessor(),new JdbcConnection(connection))){migration.update(new Contexts());migration.update(new Contexts());}assertEquals(10,db.queryForObject("SELECT COUNT(*) FROM DATABASECHANGELOG",Long.class));}
    @BeforeEach void fixture(){owner=users.incrementAndGet();db.update("INSERT INTO sys_user VALUES(?,1,0,?)",owner,"skill-fixture-"+owner);env=new MockEnvironment().withProperty("features.ai-skills-enabled","true");skills=new AiSkillService(db,json,manager,env);conversations=new ConversationService(new ConversationDao(db),json,manager);evidence=new ConversationEvidenceService(db,json);evidence.setEnabled(true);evidence.setTransactions(manager);var core=new AgentToolExecutionCore(db,json);core.setEnabled(true);core.setTechnicalEnabled(true);core.setEvidence(evidence);tools=new AgentToolService(db,json,manager);tools.setEnabled(true);tools.setTechnicalEnabled(true);tools.setSkills(skills);ReflectionTestUtils.setField(tools,"executionCore",core);ai=new AiExecutionService(db,json,manager);ai.setEnabled(true);ai.setSkills(skills);ai.setEvidence(evidence);ai.setAgentTools(provider(AgentToolService.class,tools));conversations.setAiExecution(ai);conversation=conversations.create(owner,new CreateConversation("Skill fixture",null)).id();}
    @AfterEach void retain(){ai.cancelActive(conversation);}
    Task run(String text){conversations.send(owner,conversation,new SendMessage(uuid(),List.of(new MessagePart("text",text,null,null,null,null,null,null))));Task task=ai.claim(new Claim("skill-fixture"));assertNotNull(task);assertEquals(conversation,task.conversationId());return task;}
    void select(String skill,String request){skills.select(owner,conversation,new AiSkillService.Request(request,skill,skill==null?null:1),null);}
    @Test void fixedCatalogOwnerSelectionAndClientIdConflicts(){assertEquals(2,((List<?>)skills.catalog().get("items")).size());select("materials_guidance","request");assertEquals("materials_guidance",skills.selection(owner,conversation,null).selection().id());assertThrows(ConversationProblem.class,()->skills.select(owner,conversation,new AiSkillService.Request("request","evidence_summary",1),null));assertThrows(ConversationProblem.class,()->skills.select(owner+1,conversation,new AiSkillService.Request(uuid(),"evidence_summary",1),null));assertThrows(ConversationProblem.class,()->skills.select(owner,conversation,new AiSkillService.Request(uuid(),"arbitrary_url",1),null));assertThrows(ConversationProblem.class,()->skills.select(owner,conversation,new AiSkillService.Request(uuid(),"evidence_summary",2),null));select(null,"clear");assertNull(skills.selection(owner,conversation,null).selection());assertEquals(2,count("SELECT COUNT(*) FROM ai_skill_selection_audit WHERE conversation_id=?",conversation));}
    @Test void normalRunCapturesImmutableVersionTrustedInstructionAndOnlyAllowedToolSchemas(){select("materials_guidance",uuid());Task task=run("Please inspect the materials already in this conversation");assertEquals("materials_guidance",task.skill().id());assertEquals(1,task.skill().version());assertEquals("system",task.messages().getFirst().role());assertTrue(task.messages().getFirst().content().contains("not conversation evidence"));assertTrue(task.messages().getFirst().content().contains("unverified attachment observations"));assertEquals(Set.of("read_conversation_history","read_conversation_evidence"),task.tools().stream().map(tool->tool.path("function").path("name").asText()).collect(java.util.stream.Collectors.toSet()));String snapshot=db.queryForObject("SELECT instruction_text FROM ai_skill_run_snapshot WHERE run_id=?",String.class,task.runId());select("evidence_summary",uuid());assertEquals("materials_guidance",skills.snapshot(task.runId()).id());assertEquals(snapshot,db.queryForObject("SELECT instruction_text FROM ai_skill_run_snapshot WHERE run_id=?",String.class,task.runId()));ai.cancel(owner,conversation,task.runId());assertEquals("evidence_summary",run("Summarize this conversation").skill().id());}
    @Test void hostileWorkerCannotExecuteHiddenRegisteredTechnicalToolAndHistoryStillExecutes(){select("evidence_summary",uuid());Task task=run("Read previous conversation");var rejected=new Proposal(task.leaseToken(),task.attempt(),task.controlEpoch(),1,List.of(new Call("hidden","server_capabilities",json.createObjectNode())));assertEquals("SKILL_TOOL_NOT_ALLOWED",assertThrows(ConversationProblem.class,()->tools.submitCalls(task.runId(),rejected)).getMessage());assertEquals(0,count("SELECT COUNT(*) FROM agent_tool_call WHERE run_id=?",task.runId()));var args=json.createObjectNode().put("limit",5);var accepted=tools.submitCalls(task.runId(),new Proposal(task.leaseToken(),task.attempt(),task.controlEpoch(),1,List.of(new Call("history","read_conversation_history",args))));assertEquals("succeeded",accepted.results().getFirst().status());assertTrue(accepted.results().getFirst().output().toString().contains("Read previous conversation"));}
    @Test void flagOffRetainsExistingSubsetAndSnapshotWhileFutureRunsUseLegacyWire(){select("evidence_summary",uuid());Task old=run("old bounded run");env.setProperty("features.ai-skills-enabled","false");assertEquals("evidence_summary",skills.snapshot(old.runId()).id());assertThrows(ConversationProblem.class,()->skills.requireTool(old.runId(),"server_capabilities"));assertThrows(ConversationProblem.class,()->skills.selection(owner,conversation,null));ai.cancel(owner,conversation,old.runId());Task next=run("next ordinary run");assertNull(next.skill());assertTrue(next.tools().stream().anyMatch(tool->tool.path("function").path("name").asText().equals("server_capabilities")));assertNotEquals("system",next.messages().getFirst().role());}
    @Test void tamperedVersionedSnapshotFailsClosedAndContextBudgetIsBounded(){select("evidence_summary",uuid());Task task=run("bounded");var source=List.of(new ContextMessage("user","a".repeat(64000)),new ContextMessage("user","latest authorized question"));var bounded=skills.applyContext(task.runId(),source);assertTrue(bounded.stream().mapToInt(item->item.content().length()).sum()<=64000);assertEquals("latest authorized question",bounded.getLast().content());db.update("UPDATE ai_skill_run_snapshot SET instruction_text='untrusted replaced template' WHERE run_id=?",task.runId());assertThrows(ConversationProblem.class,()->skills.snapshot(task.runId()));assertThrows(ConversationProblem.class,()->skills.requireTool(task.runId(),"read_conversation_history"));}
    @Test void clearedSelectionDoesNotChangeExistingRunAndNoSkillLeavesLegacyTaskFieldAbsent()throws Exception{Task ordinary=run("ordinary");assertNull(ordinary.skill());assertFalse(json.valueToTree(ordinary).has("skill"));ai.cancel(owner,conversation,ordinary.runId());select("materials_guidance",uuid());Task selected=run("selected");select(null,uuid());assertEquals("materials_guidance",skills.snapshot(selected.runId()).id());assertEquals(1,count("SELECT COUNT(*) FROM ai_skill_run_snapshot WHERE run_id=?",selected.runId()));}
    long count(String sql,Object...args){return db.queryForObject(sql,Long.class,args);}static String uuid(){return UUID.randomUUID().toString().replace("-","");}
}
